def find_path(root, target, path):
    if root is None:
        return False
    path.append(root)
    if root.val == target:
        return True
    if find_path(root.left, target, path) or find_path(root.right, target, path):
        return True
    path.pop()                                            # backtrack if target not found this way
    return False

def lca_brute(root, p, q):
    path_p, path_q = [], []
    find_path(root, p, path_p)
    find_path(root, q, path_q)
    lca = None
    for a, b in zip(path_p, path_q):
        if a is b:
            lca = a                                          # track the last matching node
        else:
            break
    return lca

