public class Main {
    static TreeNode lowestCommonAncestor(TreeNode root, int p, int q) {
        if (root == null || root.val == p || root.val == q) return root;
        TreeNode left = lowestCommonAncestor(root.left, p, q);
        TreeNode right = lowestCommonAncestor(root.right, p, q);
        if (left != null && right != null) return root;              // found on OPPOSITE sides: this IS the LCA
        return left != null ? left : right;                             // otherwise pass along whichever side found something
    }
}

